@block BeaverAero begin
    # Aerodynamic force and moment coefficients of the DHC-2 'Beaver' (generated by
    # design/build_model.py from design/beaver_data.py). Polynomials identified from flight tests
    # by Tjee & Mulder (TU Delft report LR-556, 1988), as in the FDC 1.4 toolbox [FDC modbuild.m,
    # REP Table C.3]; body axes FRD, angles in rad, valid for 35-55 m/s in the normal flight
    # envelope (no stall). With ph = p b/2V, qh = q c/V, rh = r b/2V:
    #   CX = CX0 + CXa a + CXa2 a * a + CXa3 a * a * a + CXq qh + CXdr dr_r + CXdf df_r + CXadf a * df_r
    #   CY = CY0 + CYb beta + CYp ph + CYr rh + CYda da_r + CYdr dr_r + CYdra dr_r * a
    #   CZ = CZ0 + CZa a + CZa3 a * a * a + CZq qh + CZde de_r + CZdeb2 de_r * beta * beta + CZdf df_r + CZadf a * df_r
    #   Cl = Cl0 + Clb beta + Clp ph + Clr rh + Clda da_r + Cldr dr_r + Cldaa da_r * a
    #   Cm = Cm0 + Cma a + Cma2 a * a + Cmq qh + Cmde de_r + Cmb2 beta * beta + Cmr rh + Cmdf df_r
    #   Cn = Cn0 + Cnb beta + Cnp ph + Cnr rh + Cnda da_r + Cndr dr_r + Cnq qh + Cnb3 beta * beta * beta
    # The beta-dot term (CYbdot) is not here: BeaverWrench applies it the way FDC does.
    @inputs begin
        V::Real, [unit = "m/s"]
        alpha::Real, [unit = "rad"]
        beta::Real, [unit = "rad"]
        p::Real, [unit = "rad/s"]
        q::Real, [unit = "rad/s"]
        r::Real, [unit = "rad/s"]
        de::Real, [description = "Elevator (deg), positive trailing edge down"]
        da::Real, [description = "Ailerons (deg), da_right - da_left, positive rolls left"]
        dr::Real, [description = "Rudder (deg), positive trailing edge left"]
        df::Real, [description = "Flaps (deg), positive down"]
    end
    @outputs begin
        CX::Real
        CY::Real
        CZ::Real
        Cl::Real
        Cm::Real
        Cn::Real
    end
    @parameters begin
        b::Real = 14.63, [unit = "m", description = "Span"]
        c::Real = 1.5875, [unit = "m", description = "Mean aerodynamic chord"]
        CX0::Real = -0.03554
        CXa::Real = 0.00292
        CXa2::Real = 5.459
        CXa3::Real = -5.162
        CXq::Real = -0.6748
        CXdr::Real = 0.03412
        CXdf::Real = -0.09447
        CXadf::Real = 1.106
        CY0::Real = -0.002226
        CYb::Real = -0.7678
        CYp::Real = -0.124
        CYr::Real = 0.3666
        CYda::Real = -0.02956
        CYdr::Real = 0.1158
        CYdra::Real = 0.5238
        CZ0::Real = -0.05504
        CZa::Real = -5.578
        CZa3::Real = 3.442
        CZq::Real = -2.988
        CZde::Real = -0.398
        CZdeb2::Real = -15.93
        CZdf::Real = -1.377
        CZadf::Real = -1.261
        Cl0::Real = 0.000591
        Clb::Real = -0.0618
        Clp::Real = -0.5045
        Clr::Real = 0.1695
        Clda::Real = -0.09917
        Cldr::Real = 0.006934
        Cldaa::Real = -0.08269
        Cm0::Real = 0.09448
        Cma::Real = -0.6028
        Cma2::Real = -2.14
        Cmq::Real = -15.56
        Cmde::Real = -1.921
        Cmb2::Real = 0.6921
        Cmr::Real = -0.3118
        Cmdf::Real = 0.4072
        Cn0::Real = -0.003117
        Cnb::Real = 0.006719
        Cnp::Real = -0.1585
        Cnr::Real = -0.1112
        Cnda::Real = -0.003872
        Cndr::Real = -0.08265
        Cnq::Real = 0.1595
        Cnb3::Real = 0.1373
    end
    @variables begin
        a::Real = 0.0
        ph::Real = 0.0
        qh::Real = 0.0
        rh::Real = 0.0
        de_r::Real = 0.0
        da_r::Real = 0.0
        dr_r::Real = 0.0
        df_r::Real = 0.0
    end
    @equations begin
        a ~ alpha
        ph ~ p * b / (2.0 * V)
        qh ~ q * c / V
        rh ~ r * b / (2.0 * V)
        de_r ~ de / 57.29577951308232
        da_r ~ da / 57.29577951308232
        dr_r ~ dr / 57.29577951308232
        df_r ~ df / 57.29577951308232
        CX ~ CX0 + CXa * a + CXa2 * a * a + CXa3 * a * a * a + CXq * qh + CXdr * dr_r + CXdf * df_r + CXadf * a * df_r
        CY ~ CY0 + CYb * beta + CYp * ph + CYr * rh + CYda * da_r + CYdr * dr_r + CYdra * dr_r * a
        CZ ~ CZ0 + CZa * a + CZa3 * a * a * a + CZq * qh + CZde * de_r + CZdeb2 * de_r * beta * beta + CZdf * df_r + CZadf * a * df_r
        Cl ~ Cl0 + Clb * beta + Clp * ph + Clr * rh + Clda * da_r + Cldr * dr_r + Cldaa * da_r * a
        Cm ~ Cm0 + Cma * a + Cma2 * a * a + Cmq * qh + Cmde * de_r + Cmb2 * beta * beta + Cmr * rh + Cmdf * df_r
        Cn ~ Cn0 + Cnb * beta + Cnp * ph + Cnr * rh + Cnda * da_r + Cndr * dr_r + Cnq * qh + Cnb3 * beta * beta * beta
    end
end
